// src/client/workflows/use-workflow-session.ts
function useWorkflowSession(definitionId, rpc, sessions) {
  const topics = useDiscussionTopics(definitionId, rpc, sessions, "workflow");
  const state = topics.snapshot;
  return {
    ...topics,
    binding: state ? {
      definitionId: state.definitionId,
      sessionId: state.selected.sessionId,
      directory: state.directory
    } : null
  };
}

// src/client/workflows/workflow-session-policy.js
function workflowSessionReady(definitionId, binding, selectedSessionId) {
  return !!binding && binding.definitionId === definitionId && binding.sessionId === selectedSessionId && binding.sessionId.startsWith("crystra-workflow-");
}

