// src/client/task-workbench/workbench-store.ts
function createWorkbenchStore() {
  return defineStore({
    init: () => ({ surfaces: {}, attention: {}, systemFocus: {} }),
    actions: {
      select(state, taskId, surface) {
        state.surfaces[`task:${taskId}`] = surface;
      },
      /** Caller supplies an authoritative surface snapshot, not chat/log row counts. */
      receiveAttention(state, taskId, surface, snapshot) {
        const key2 = `task:${taskId}`;
        const task = state.attention[key2] ?? (state.attention[key2] = {});
        const previous2 = task[surface];
        task[surface] = {
          revision: snapshot.revision,
          messageIds: [...new Set(snapshot.messageIds)],
          seenRevision: previous2?.seenRevision,
          readMessageIds: previous2?.readMessageIds ?? []
        };
      },
      /** Call only after this exact revision and these notifications were actually viewed. */
      markViewed(state, taskId, surface, displayed) {
        const entry = state.attention[`task:${taskId}`]?.[surface];
        if (!entry) return;
        if (entry.seenRevision !== entry.revision)
          entry.seenRevision = displayed.revision;
        entry.readMessageIds = [
          .../* @__PURE__ */ new Set([...entry.readMessageIds, ...displayed.messageIds])
        ];
      },
      setSystemFocus(state, taskId, surface) {
        state.systemFocus[`task:${taskId}`] = surface;
      }
    }
  });
}

